package com.bank.processing;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ProcessingDemo {
    private static final Logger log = Logger.getLogger("Proc");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Transaction> dayTxns = List.of(
            new Transaction("SAV2001", new BigDecimal("50000")),
            new Transaction("CUR3001", new BigDecimal("10000")),
            new Transaction("SAV2001", new BigDecimal("600000")),   // suspicious (large)
            new Transaction("SAV2001", new BigDecimal("20000")),
            new Transaction("CUR3001", new BigDecimal("5000")));

        // STREAM: react to each transaction as it arrives (low latency)
        log.info("STREAM processing (real-time fraud):");
        StreamProcessor stream = new StreamProcessor(new BigDecimal("500000"));
        for (Transaction t : dayTxns) stream.onEvent(t);  // processed one by one, immediately

        // BATCH: process the full day's data at once (throughput, completeness)
        log.info("BATCH processing (end-of-day):");
        BatchProcessor batch = new BatchProcessor();
        Map<String,BigDecimal> interest = batch.computeDailyInterest(dayTxns);
        log.info(() -> "daily interest: " + interest);
        BigDecimal total = batch.reconcileTotal(dayTxns);
        log.info(() -> "reconciliation total = " + total);
    }
}

