package com.bank.processing;

import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;

// Batch: process the entire bounded dataset in one pass for throughput + completeness.
public class BatchProcessor {

    // daily interest = sum per account × rate, over the full day's data
    public Map<String,BigDecimal> computeDailyInterest(List<Transaction> txns) {
        Map<String,BigDecimal> perAccount = txns.stream().collect(Collectors.groupingBy(
            Transaction::accountId,
            Collectors.reducing(BigDecimal.ZERO, Transaction::amount, BigDecimal::add)));
        BigDecimal rate = new BigDecimal("0.0001");
        Map<String,BigDecimal> interest = new LinkedHashMap<>();
        perAccount.forEach((acc, sum) -> interest.put(acc, sum.multiply(rate)));
        return interest;
    }

    // reconciliation: total across the complete dataset (correctness over all rows)
    public BigDecimal reconcileTotal(List<Transaction> txns) {
        return txns.stream().map(Transaction::amount).reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
